import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import {normalizeSkillDefinition} from './local-skills.mjs';

export const operationalKinds=['projects','tasks','habits','journal_metadata','inbox_items','agents','skills','skill_runs','agent_workflow_runs','area_records','weekly_plans','weekly_outcomes','focus_proposals','vault_write_proposals','approvals','progress_items','audit_log'] as const;
export type OperationalKind=typeof operationalKinds[number];
const stateDir=()=>path.join(process.cwd(),'local-state');
const dbPath=()=>path.join(stateDir(),'agentic-os.sqlite');
let database:DatabaseSync|null=null;

const migrations=[{version:1,sql:`
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,title TEXT NOT NULL,status TEXT NOT NULL,data_json TEXT NOT NULL,sensitive_enc TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,project_id TEXT,title TEXT NOT NULL,status TEXT NOT NULL,due_at TEXT,data_json TEXT NOT NULL,sensitive_enc TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS habits(id TEXT PRIMARY KEY,title TEXT NOT NULL,cadence TEXT NOT NULL,data_json TEXT NOT NULL,sensitive_enc TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS journal_metadata(id TEXT PRIMARY KEY,entry_date TEXT NOT NULL,mood TEXT,energy INTEGER,data_json TEXT NOT NULL,sensitive_enc TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inbox_items(id TEXT PRIMARY KEY,item_type TEXT NOT NULL,status TEXT NOT NULL,data_json TEXT NOT NULL,sensitive_enc TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL,config_json TEXT NOT NULL,sensitive_enc TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS skills(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL,config_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,action_type TEXT NOT NULL,status TEXT NOT NULL,exact_diff_json TEXT NOT NULL,expires_at TEXT NOT NULL,decided_at TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS progress_items(id TEXT PRIMARY KEY,phase TEXT NOT NULL,status TEXT NOT NULL,evidence_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,metadata_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS migration_previews(id TEXT PRIMARY KEY,device_id TEXT NOT NULL,payload_hash TEXT NOT NULL,keys_json TEXT NOT NULL,conflict_count INTEGER NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);`},{version:2,sql:`ALTER TABLE habits ADD COLUMN status TEXT NOT NULL DEFAULT 'active';ALTER TABLE journal_metadata ADD COLUMN status TEXT NOT NULL DEFAULT 'active';`},{version:3,sql:`CREATE TABLE IF NOT EXISTS area_records(id TEXT PRIMARY KEY,area TEXT NOT NULL,record_type TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL,data_json TEXT NOT NULL,sensitive_enc TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS area_records_area_type_idx ON area_records(area,record_type,status);`},{version:4,sql:`CREATE TABLE IF NOT EXISTS weekly_plans(id TEXT PRIMARY KEY,week_start TEXT NOT NULL,status TEXT NOT NULL,plan_enc TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS weekly_plans_week_idx ON weekly_plans(week_start,updated_at);`},{version:5,sql:`CREATE TABLE IF NOT EXISTS weekly_outcomes(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL,source_kind TEXT NOT NULL,source_id TEXT,rank INTEGER NOT NULL,status TEXT NOT NULL,title_enc TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,FOREIGN KEY(plan_id) REFERENCES weekly_plans(id));CREATE TABLE IF NOT EXISTS focus_proposals(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL,outcome_id TEXT NOT NULL,target_calendar_id TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,timezone TEXT NOT NULL,status TEXT NOT NULL,proposal_enc TEXT NOT NULL,approval_ref TEXT,audit_ref TEXT,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,FOREIGN KEY(plan_id) REFERENCES weekly_plans(id),FOREIGN KEY(outcome_id) REFERENCES weekly_outcomes(id));CREATE INDEX IF NOT EXISTS weekly_outcomes_plan_idx ON weekly_outcomes(plan_id,rank);CREATE INDEX IF NOT EXISTS focus_proposals_plan_idx ON focus_proposals(plan_id,start_at);`},{version:6,sql:`CREATE TABLE IF NOT EXISTS agent_workflow_runs(id TEXT PRIMARY KEY,workflow_id TEXT NOT NULL,status TEXT NOT NULL,current_step TEXT NOT NULL,input_enc TEXT NOT NULL,output_enc TEXT NOT NULL,source_json TEXT NOT NULL,decision_json TEXT NOT NULL,resume_enc TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS agent_workflow_runs_workflow_idx ON agent_workflow_runs(workflow_id,updated_at);`},{version:7,sql:`CREATE TABLE IF NOT EXISTS skill_runs(id TEXT PRIMARY KEY,skill_id TEXT NOT NULL,definition_version INTEGER NOT NULL,status TEXT NOT NULL,input_enc TEXT NOT NULL,output_enc TEXT NOT NULL,source_json TEXT NOT NULL,safety_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(skill_id) REFERENCES skills(id));CREATE INDEX IF NOT EXISTS skill_runs_skill_idx ON skill_runs(skill_id,updated_at);`},{version:8,sql:`CREATE TABLE IF NOT EXISTS vault_write_proposals(id TEXT PRIMARY KEY,proposal_type TEXT NOT NULL,status TEXT NOT NULL,target_path_enc TEXT NOT NULL,proposal_enc TEXT NOT NULL,approval_hash TEXT NOT NULL,expires_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS vault_write_proposals_status_idx ON vault_write_proposals(status,updated_at);`}];

function db(){if(database)return database;fs.mkdirSync(stateDir(),{recursive:true});database=new DatabaseSync(dbPath());database.exec('PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000; CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);');const applied=new Set((database.prepare('SELECT version FROM schema_migrations').all() as Array<{version:number}>).map(row=>row.version));for(const migration of migrations){if(applied.has(migration.version))continue;database.exec('BEGIN IMMEDIATE');try{database.exec(migration.sql);database.prepare('INSERT INTO schema_migrations(version,applied_at) VALUES(?,?)').run(migration.version,new Date().toISOString());database.exec('COMMIT')}catch(error){database.exec('ROLLBACK');throw error}}return database}
export function withStoreTransaction<T>(operation:()=>T){const database=db();database.exec('BEGIN IMMEDIATE');try{const result=operation();database.exec('COMMIT');return result}catch(error){database.exec('ROLLBACK');throw error}}
function fieldKey(){const secret=process.env.AUTH_SECRET;if(!secret)throw new Error('AUTH_SECRET fehlt');return crypto.createHash('sha256').update(`agentic-os-sensitive-fields:${secret}`).digest()}
export function encryptSensitive(value:unknown){const iv=crypto.randomBytes(12),cipher=crypto.createCipheriv('aes-256-gcm',fieldKey(),iv),encrypted=Buffer.concat([cipher.update(JSON.stringify(value),'utf8'),cipher.final()]);return[iv.toString('base64url'),cipher.getAuthTag().toString('base64url'),encrypted.toString('base64url')].join('.')}
export function decryptSensitive(value:string){const[iv,tag,data]=value.split('.'),decipher=crypto.createDecipheriv('aes-256-gcm',fieldKey(),Buffer.from(iv,'base64url'));decipher.setAuthTag(Buffer.from(tag,'base64url'));return JSON.parse(Buffer.concat([decipher.update(Buffer.from(data,'base64url')),decipher.final()]).toString('utf8'))}
export function storeStatus(){const counts=Object.fromEntries(operationalKinds.map(table=>[table,Number((db().prepare(`SELECT COUNT(*) AS count FROM ${table}`).get() as {count:number}).count)]));const version=(db().prepare('SELECT MAX(version) AS version FROM schema_migrations').get() as {version:number}).version,legacyJournalPlaintextRows=Number((db().prepare("SELECT COUNT(*) AS count FROM journal_metadata WHERE json_type(data_json,'$.text') IS NOT NULL").get() as {count:number}).count),legacyInboxPlaintextRows=Number((db().prepare("SELECT COUNT(*) AS count FROM inbox_items WHERE json_type(data_json,'$.content') IS NOT NULL").get() as {count:number}).count);return{online:true,engine:'node:sqlite',schemaVersion:version,counts,localOnly:true,wal:true,conflictGate:true,sensitiveFieldEncryption:'AES-256-GCM',legacyJournalPlaintextRows,legacyInboxPlaintextRows}}
export function createMigrationPreview(deviceId:string,keys:string[]){const normalized=[...new Set(keys.filter(key=>/^aos:(tasks|journal|brand|inbox)$/.test(key)))].sort();const mapping:Record<string,OperationalKind>={'aos:tasks':'tasks','aos:journal':'journal_metadata','aos:brand':'progress_items','aos:inbox':'inbox_items'};const conflicts=normalized.filter(key=>Number((db().prepare(`SELECT COUNT(*) AS count FROM ${mapping[key]}`).get() as {count:number}).count)>0).length;const id=crypto.randomUUID(),createdAt=new Date().toISOString(),hash=crypto.createHash('sha256').update(JSON.stringify(normalized)).digest('hex');db().prepare('INSERT INTO migration_previews(id,device_id,payload_hash,keys_json,conflict_count,status,created_at) VALUES(?,?,?,?,?,?,?)').run(id,deviceId,hash,JSON.stringify(normalized),conflicts,'review_required',createdAt);return{id,deviceId,discoveredKeys:normalized,conflictCount:conflicts,status:'review_required',writesPerformed:false,createdAt}}
export function registerExternalApproval(id:string,actionType:string,exactDiff:unknown,expiresAt:string){if(!/^[0-9a-f-]{36}$/i.test(id))throw new Error('Ungültige Freigabe-ID');if(!/^calendar_event_(create|update)$/.test(actionType))throw new Error('Ungültige Freigabeklasse');if(!Number.isFinite(Date.parse(expiresAt))||Date.parse(expiresAt)<=Date.now())throw new Error('Ungültige Freigabefrist');const now=new Date().toISOString();db().exec('BEGIN IMMEDIATE');try{db().prepare('INSERT INTO approvals(id,action_type,status,exact_diff_json,expires_at,version,updated_at) VALUES(?,?,?,?,?,1,?)').run(id,actionType,'review_required',encryptSensitive(exactDiff),expiresAt,now);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'approval.create','approval',id,JSON.stringify({actionType,status:'review_required',externalActionsPerformed:false}),now);db().exec('COMMIT')}catch(error){db().exec('ROLLBACK');throw error}return{id,status:'review_required',expiresAt}}
export function consumeExternalApproval(id:string,actionType:string,exactDiff:unknown){if(!/^[0-9a-f-]{36}$/i.test(id))throw new Error('Ungültige Freigabe-ID');const database=db(),row=database.prepare('SELECT action_type,status,exact_diff_json,expires_at,version FROM approvals WHERE id=?').get(id) as Record<string,any>|undefined;if(!row||row.action_type!==actionType)throw new Error('Freigabe nicht gefunden');if(row.status!=='review_required')throw new Error('Freigabe wurde bereits verwendet');if(Date.now()>Date.parse(String(row.expires_at)))throw new Error('Vorschlag ist abgelaufen');const expected=crypto.createHash('sha256').update(JSON.stringify(decryptSensitive(String(row.exact_diff_json)))).digest(),actual=crypto.createHash('sha256').update(JSON.stringify(exactDiff)).digest();if(expected.length!==actual.length||!crypto.timingSafeEqual(expected,actual))throw new Error('Exakte Freigabe stimmt nicht mehr überein');const now=new Date().toISOString();database.exec('BEGIN IMMEDIATE');try{const result=database.prepare("UPDATE approvals SET status='consumed',decided_at=?,version=version+1,updated_at=? WHERE id=? AND status='review_required' AND version=?").run(now,now,id,Number(row.version));if(!result.changes)throw new Error('Freigabe wurde bereits verwendet');database.prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'approval.consume','approval',id,JSON.stringify({actionType,status:'consumed',externalActionAuthorized:true}),now);database.exec('COMMIT')}catch(error){database.exec('ROLLBACK');throw error}return{id,status:'consumed',consumedAt:now}}
const crudKinds=['projects','tasks','habits','journal_metadata','inbox_items','agents','skills','area_records'] as const;export type CrudKind=typeof crudKinds[number];
export function isCrudKind(value:string):value is CrudKind{return(crudKinds as readonly string[]).includes(value)}
const areaTypes:Record<string,readonly string[]>={faith:['practice','quran','dua','reflection'],health:['training','nutrition','recovery','measurement'],finance:['account','income','expense','budget','goal','recurring'],relations:['person','contact','birthday','follow_up','note'],career:['goal','task','learning','opportunity','milestone','document']};
export function validateRecord(kind:CrudKind,input:any){const title=String(input?.title||input?.name||'').trim();if(title.length<2||title.length>120)throw new Error('Name muss 2–120 Zeichen haben');const status=String(input?.status||'active');if(!['active','planned','paused','completed','archived','metadata_only'].includes(status))throw new Error('Ungültiger Status');if(kind==='projects'){const goal=String(input?.goal||'').trim(),description=String(input?.description||'').trim(),nextAction=String(input?.nextAction||'').trim(),dueDate=String(input?.dueDate||'').trim();if(goal.length>1200)throw new Error('Projektziel darf höchstens 1200 Zeichen haben');if(description.length>4000)throw new Error('Projektbeschreibung darf höchstens 4000 Zeichen haben');if(nextAction.length>500)throw new Error('Nächste Aktion darf höchstens 500 Zeichen haben');if(dueDate&&!/^\d{4}-\d{2}-\d{2}$/.test(dueDate))throw new Error('Projekttermin muss ein gültiges Datum sein')}if((kind==='tasks'||kind==='inbox_items')&&input?.projectId&&!/^[0-9a-f-]{36}$/i.test(String(input.projectId)))throw new Error('Ungültige Projektzuordnung');if(kind==='tasks'){const dueAt=String(input?.dueAt||'').trim(),priority=String(input?.priority||'medium'),area=String(input?.area||'Inbox'),checklist=input?.checklist||[];if(dueAt&&!/^\d{4}-\d{2}-\d{2}$/.test(dueAt))throw new Error('Fälligkeit muss ein gültiges Datum sein');if(!['low','medium','high'].includes(priority))throw new Error('Ungültige Priorität');if(!['Inbox','Glaube','Karriere','Gesundheit','Finanzen','Beziehungen','Projekte'].includes(area))throw new Error('Ungültiger Aufgabenbereich');if(!Array.isArray(checklist)||checklist.length>20||checklist.some((item:any)=>!item||!/^[-0-9a-f]{36}$/i.test(String(item.id))||typeof item.done!=='boolean'||String(item.label||'').trim().length<1||String(item.label).trim().length>160))throw new Error('Aufgaben-Checkliste ist ungültig')}if(kind==='habits'){const cadence=String(input?.cadence||'daily'),completedOn=input?.completedOn||[];if(!['daily','weekly'].includes(cadence))throw new Error('Habit-Rhythmus muss täglich oder wöchentlich sein');if(!Array.isArray(completedOn)||completedOn.length>90||completedOn.some((value:any)=>!/^\d{4}-\d{2}-\d{2}$/.test(String(value))))throw new Error('Habit-Abschlüsse sind ungültig')}if(kind==='area_records'){const area=String(input?.area||''),recordType=String(input?.recordType||'');if(!areaTypes[area]?.includes(recordType))throw new Error('Ungültiger Bereich oder Eintragstyp');const details=String(input?.details||'');if(details.length>4000)throw new Error('Details dürfen höchstens 4000 Zeichen haben');const track=String(input?.track||'');if(area==='career'&&!['employee','business'].includes(track))throw new Error('Karrierepfad fehlt');if(area!=='career'&&track)throw new Error('Karrierepfad nur für Karriere erlaubt');for(const field of ['date','birthday','lastContact','nextFollowUp']){const value=String(input?.[field]||'');if(value&&!/^\d{4}-\d{2}-\d{2}$/.test(value))throw new Error(`${field} muss ein gültiges Datum sein`)}for(const field of ['amount','targetAmount','durationMinutes','recoveryScore','sleepHours','metricValue','quranPage','pagesRead']){const value=String(input?.[field]??'');if(value&&!/^-?\d+(?:[.,]\d{1,2})?$/.test(value))throw new Error(`${field} muss numerisch sein`)}const quranPage=Number(String(input?.quranPage||'0').replace(',','.')),pagesRead=Number(String(input?.pagesRead||'0').replace(',','.')),duration=Number(String(input?.durationMinutes||'0').replace(',','.')),recovery=Number(String(input?.recoveryScore||'0').replace(',','.')),sleep=Number(String(input?.sleepHours||'0').replace(',','.'));if(quranPage&&(quranPage<1||quranPage>604))throw new Error('Qurʾān-Seite muss zwischen 1 und 604 liegen');if(pagesRead&&(pagesRead<1||pagesRead>604))throw new Error('Gelesene Seiten müssen zwischen 1 und 604 liegen');if(duration&&(duration<1||duration>1440))throw new Error('Trainingsdauer muss zwischen 1 und 1440 Minuten liegen');if(recovery&&(recovery<1||recovery>5))throw new Error('Recovery-Wert muss zwischen 1 und 5 liegen');if(sleep&&(sleep<0||sleep>24))throw new Error('Schlafdauer muss zwischen 0 und 24 Stunden liegen');if(input?.prayerName&&!['fajr','dhuhr','asr','maghrib','isha','other'].includes(String(input.prayerName)))throw new Error('Ungültige Gebetsauswahl');if(input?.intensity&&!['easy','moderate','hard'].includes(String(input.intensity)))throw new Error('Ungültige Intensität');if(input?.frequency&&!['weekly','monthly','quarterly','yearly'].includes(String(input.frequency)))throw new Error('Ungültiger Rhythmus');if(input?.relationshipCategory&&!['family','friend','romantic','professional','other'].includes(String(input.relationshipCategory)))throw new Error('Ungültige Beziehungskategorie');if(input?.constellationSlot&&!/^[1-8]$/.test(String(input.constellationSlot)))throw new Error('Ungültiger Platz in der Beziehungsansicht')}return{...input,title,name:title,status}}
export function validateAgentConfig(input:any){const areas:string[]=Array.isArray(input?.areas)?[...new Set<string>(input.areas.map((value:unknown)=>String(value)))]:[],providerMode=String(input?.providerMode||'none'),model=String(input?.model||'none'),status=String(input?.status||'metadata_only');if(areas.some(area=>!['faith','career','health','finance','relations','projects'].includes(area)))throw new Error('Agent enthält einen ungültigen Lebensbereich');if(!['subscription','none'].includes(providerMode))throw new Error('Nur Companion oder kein Provider sind ohne Kostenfreigabe erlaubt');if(!['chatgpt-companion-manual','none'].includes(model))throw new Error('Nicht verifiziertes Agentenmodell');if(providerMode==='subscription'&&model!=='chatgpt-companion-manual')throw new Error('Companion-Modus benötigt die manuelle ChatGPT-Übergabe');if(providerMode==='none'&&model!=='none')throw new Error('Ohne Provider darf kein Modell gewählt sein');if(!['metadata_only','paused'].includes(status))throw new Error('Eigene Agent-Konfiguration ist nicht ausführbar');return{...input,areas,providerMode,model,status}}
function areaRecordPayload(data:any,id:string){const{area,recordType,title,status}=data;const sensitiveFields=['details','date','amount','targetAmount','currency','track','prayerName','completed','quranPage','pagesRead','durationMinutes','intensity','recoveryScore','sleepHours','mealType','metricValue','unit','category','frequency','birthday','lastContact','nextFollowUp','relationshipCategory','constellationSlot'];const sensitive=Object.fromEntries(sensitiveFields.map(field=>[field,typeof data[field]==='boolean'?data[field]:String(data[field]??(field==='currency'?'EUR':''))]));return{publicData:JSON.stringify({id,area,recordType,title,name:title,status}),sensitive:encryptSensitive(sensitive)}}
export function listRecords(kind:CrudKind){const rows=db().prepare(`SELECT * FROM ${kind} WHERE status <> 'archived' ORDER BY updated_at DESC`).all() as Array<Record<string,any>>;return rows.map(row=>{const visible=JSON.parse(String(row.data_json||row.config_json||'{}'));if(kind==='journal_metadata')delete visible.text;if(kind==='inbox_items')delete visible.content;const sensitive=(kind==='area_records'||kind==='journal_metadata'||kind==='inbox_items')&&row.sensitive_enc?decryptSensitive(String(row.sensitive_enc)):{};return{...visible,...sensitive,id:row.id,version:Number(row.version),updatedAt:row.updated_at}})}
function assertProjectLink(projectId:unknown){if(!projectId)return;const project=db().prepare("SELECT id FROM projects WHERE id=? AND status<>'archived'").get(String(projectId));if(!project)throw new Error('Zugeordnetes Projekt wurde nicht gefunden')}
const inboxItemTypes=['idee','aufgabe','notiz','chatgpt-notiz','link','dateiverweis','note','ChatGPT-Zusammenfassung'] as const;
function assertInboxShape(data:any){const itemType=String(data.itemType||'note'),content=String(data.content||'');if(!inboxItemTypes.includes(itemType as any))throw new Error('Ungültiger Inbox-Typ');if(data.agentId&&!/^[0-9a-f-]{36}$/i.test(String(data.agentId)))throw new Error('Ungültige Agentenzuordnung');if(data.area&&!['Inbox','faith','career','health','finance','relations','projects','Projekte'].includes(String(data.area)))throw new Error('Ungültiger Lebensbereich');if(content.length>8000)throw new Error('Inbox-Inhalt darf höchstens 8000 Zeichen haben');if(['link','dateiverweis'].includes(itemType)&&content.trim().length<2)throw new Error('Ressourcenverweis benötigt eine private Referenz');if(itemType==='link'&&!/^https?:\/\/[^\s]+$/i.test(content.trim()))throw new Error('Link muss eine vollständige http(s)-Adresse sein');if(data.agentId&&!db().prepare("SELECT id FROM agents WHERE id=? AND status<>'archived'").get(String(data.agentId)))throw new Error('Zugeordneter Agent wurde nicht gefunden')}
export function createRecord(kind:CrudKind,input:any){if(kind==='skills')throw new Error('Skills benötigen die sichere Prozedur-API');const data=validateRecord(kind,input);if(kind==='tasks'||kind==='inbox_items')assertProjectLink(data.projectId);if(kind==='inbox_items')assertInboxShape(data);const id=crypto.randomUUID(),now=new Date().toISOString(),storedData=data,publicData={...data};delete publicData.text;if(kind==='inbox_items')delete publicData.content;const payload=JSON.stringify({...publicData,id});if(kind==='projects')db().prepare('INSERT INTO projects(id,title,status,data_json,updated_at) VALUES(?,?,?,?,?)').run(id,data.title,data.status,JSON.stringify({...storedData,id}),now);else if(kind==='tasks')db().prepare('INSERT INTO tasks(id,project_id,title,status,due_at,data_json,updated_at) VALUES(?,?,?,?,?,?,?)').run(id,data.projectId||null,data.title,data.status,data.dueAt||null,JSON.stringify({...storedData,id}),now);else if(kind==='habits')db().prepare('INSERT INTO habits(id,title,cadence,status,data_json,updated_at) VALUES(?,?,?,?,?,?)').run(id,data.title,data.cadence||'daily',data.status,JSON.stringify({...storedData,id}),now);else if(kind==='journal_metadata')db().prepare('INSERT INTO journal_metadata(id,entry_date,mood,energy,status,data_json,sensitive_enc,updated_at) VALUES(?,?,?,?,?,?,?,?)').run(id,data.entryDate||now.slice(0,10),data.mood||null,data.energy||null,data.status,payload,data.text?encryptSensitive({text:data.text}):null,now);else if(kind==='inbox_items')db().prepare('INSERT INTO inbox_items(id,item_type,status,data_json,sensitive_enc,updated_at) VALUES(?,?,?,?,?,?)').run(id,data.itemType||'note',data.status,payload,data.content?encryptSensitive({content:data.content}):null,now);else if(kind==='agents')db().prepare('INSERT INTO agents(id,name,status,config_json,updated_at) VALUES(?,?,?,?,?)').run(id,data.name,data.status,JSON.stringify({...storedData,id}),now);else if(kind==='area_records'){const secured=areaRecordPayload(data,id);db().prepare('INSERT INTO area_records(id,area,record_type,title,status,data_json,sensitive_enc,updated_at) VALUES(?,?,?,?,?,?,?,?)').run(id,data.area,data.recordType,data.title,data.status,secured.publicData,secured.sensitive,now)}db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'create',kind,id,JSON.stringify({source:'agentic-os-ui'}),now);return{id,...storedData,text:undefined,content:undefined,version:1,updatedAt:now}}
export function updateRecord(kind:CrudKind,id:string,input:any){if(kind==='skills')throw new Error('Skills benötigen die sichere Prozedur-API');const current=listRecords(kind).find(record=>record.id===id);if(!current)throw new Error('Eintrag nicht gefunden');if(!Number.isInteger(Number(input?.version))||Number(input.version)!==Number(current.version))throw new Error('Datenkonflikt: Eintrag wurde auf einem anderen Client geändert');const data=validateRecord(kind,{...current,...input});if(kind==='tasks'||kind==='inbox_items')assertProjectLink(data.projectId);if(kind==='inbox_items')assertInboxShape(data);const now=new Date().toISOString(),payload=JSON.stringify({...data,id});let result;if(kind==='area_records'){const secured=areaRecordPayload(data,id);result=db().prepare('UPDATE area_records SET area=?,record_type=?,title=?,data_json=?,sensitive_enc=?,status=?,version=version+1,updated_at=? WHERE id=?').run(data.area,data.recordType,data.title,secured.publicData,secured.sensitive,data.status,now,id)}else if(kind==='projects')result=db().prepare('UPDATE projects SET title=?,data_json=?,status=?,version=version+1,updated_at=? WHERE id=?').run(data.title,payload,data.status,now,id);else if(kind==='tasks')result=db().prepare('UPDATE tasks SET project_id=?,title=?,due_at=?,data_json=?,status=?,version=version+1,updated_at=? WHERE id=?').run(data.projectId||null,data.title,data.dueAt||null,payload,data.status,now,id);else if(kind==='inbox_items'){const{content,...publicData}=data;result=db().prepare('UPDATE inbox_items SET item_type=?,data_json=?,sensitive_enc=?,status=?,version=version+1,updated_at=? WHERE id=?').run(data.itemType||'note',JSON.stringify({...publicData,id}),content?encryptSensitive({content}):null,data.status,now,id)}else if(kind==='journal_metadata'){const{text,...publicData}=data;result=db().prepare('UPDATE journal_metadata SET entry_date=?,mood=?,energy=?,data_json=?,sensitive_enc=?,status=?,version=version+1,updated_at=? WHERE id=?').run(data.entryDate,data.mood||null,data.energy||null,JSON.stringify({...publicData,id}),text?encryptSensitive({text}):null,data.status,now,id)}else{const column=kind==='agents'?'config_json':'data_json';result=db().prepare(`UPDATE ${kind} SET ${column}=?,status=?,version=version+1,updated_at=? WHERE id=?`).run(payload,data.status,now,id)}if(!result.changes)throw new Error('Eintrag nicht aktualisiert');db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'update',kind,id,JSON.stringify({source:'agentic-os-ui'}),now);return{id,...data,version:Number(current.version)+1,updatedAt:now}}
export function archiveRecord(kind:CrudKind,id:string,expectedVersion:number){
  if(kind==='skills')throw new Error('Skills benötigen die sichere Prozedur-API');
  db().exec('BEGIN IMMEDIATE');
  try{
    const current=db().prepare(`SELECT version FROM ${kind} WHERE id=? AND status<>'archived'`).get(id) as{version:number}|undefined;
    if(!current)throw new Error('Eintrag nicht gefunden');
    if(!Number.isInteger(expectedVersion)||expectedVersion!==Number(current.version))throw new Error('Datenkonflikt: Eintrag wurde auf einem anderen Client geändert');
    if(kind==='projects'){
      const taskCount=Number((db().prepare("SELECT COUNT(*) AS count FROM tasks WHERE project_id=? AND status<>'archived'").get(id) as{count:number}).count);
      const inboxCount=Number((db().prepare("SELECT COUNT(*) AS count FROM inbox_items WHERE json_extract(data_json,'$.projectId')=? AND status<>'archived'").get(id) as{count:number}).count);
      if(taskCount||inboxCount)throw new Error(`Projekt hat noch ${taskCount} aktive Aufgaben und ${inboxCount} Inbox-Verknüpfungen`);
    }
    if(kind==='agents'){
      const inboxCount=Number((db().prepare("SELECT COUNT(*) AS count FROM inbox_items WHERE json_extract(data_json,'$.agentId')=? AND status<>'archived'").get(id) as{count:number}).count);
      if(inboxCount)throw new Error(`Agent hat noch ${inboxCount} aktive Inbox-Verknüpfungen`);
    }
    const now=new Date().toISOString();
    const result=db().prepare(`UPDATE ${kind} SET status='archived',version=version+1,updated_at=? WHERE id=? AND version=?`).run(now,id,expectedVersion);
    if(!result.changes)throw new Error('Datenkonflikt: Eintrag wurde auf einem anderen Client geändert');
    db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'archive',kind,id,JSON.stringify({source:'agentic-os-ui',externalActionsPerformed:false}),now);
    db().exec('COMMIT');
    return{archived:true,id,externalActionsPerformed:false};
  }catch(error){db().exec('ROLLBACK');throw error}
}
const restorableStatuses=new Set(['active','planned','paused','completed','metadata_only']);
export function listArchivedRecords(){return crudKinds.flatMap(kind=>(db().prepare(`SELECT * FROM ${kind} WHERE status='archived' ORDER BY updated_at DESC`).all() as Array<Record<string,any>>).map(row=>{const payload=JSON.parse(String(row.data_json||row.config_json||'{}')),originalStatus=restorableStatuses.has(String(payload.status))?String(payload.status):'active';return{kind,id:String(row.id),title:String(payload.title||payload.name||`${kind} · archiviert`).slice(0,120),originalStatus,version:Number(row.version),archivedAt:String(row.updated_at)}})).sort((a,b)=>b.archivedAt.localeCompare(a.archivedAt))}
export function restoreArchivedRecord(kind:CrudKind,id:string,expectedVersion:number){if(!/^[0-9a-f-]{36}$/i.test(id))throw new Error('Ungültige Archiv-ID');const row=db().prepare(`SELECT * FROM ${kind} WHERE id=? AND status='archived'`).get(id) as Record<string,any>|undefined;if(!row)throw new Error('Archivierter Eintrag nicht gefunden');if(!Number.isInteger(expectedVersion)||expectedVersion!==Number(row.version))throw new Error('Datenkonflikt: Archiv wurde auf einem anderen Client geändert');const payload=JSON.parse(String(row.data_json||row.config_json||'{}')),status=restorableStatuses.has(String(payload.status))?String(payload.status):'active';if((kind==='tasks'||kind==='inbox_items')&&payload.projectId)assertProjectLink(payload.projectId);if(kind==='inbox_items'&&payload.agentId&&!db().prepare("SELECT id FROM agents WHERE id=? AND status<>'archived'").get(String(payload.agentId)))throw new Error('Zugeordneter Agent ist archiviert oder nicht verfügbar');const now=new Date().toISOString();db().exec('BEGIN IMMEDIATE');try{const result=db().prepare(`UPDATE ${kind} SET status=?,version=version+1,updated_at=? WHERE id=? AND version=? AND status='archived'`).run(status,now,id,expectedVersion);if(!result.changes)throw new Error('Datenkonflikt: Archiv wurde auf einem anderen Client geändert');db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'restore',kind,id,JSON.stringify({source:'agentic-os-archive',restoredStatus:status,externalActionsPerformed:false}),now);db().exec('COMMIT')}catch(error){db().exec('ROLLBACK');throw error}return{restored:true,deleted:false,id,kind,status,version:expectedVersion+1,externalActionsPerformed:false}}
export function listSkillDefinitions(){return listRecords('skills').map(record=>({...record,executable:record.status==='active'&&record.executionMode==='deterministic-local'&&record.approvalClass==='local_read_proposal'}))}
export function createSkillDefinition(input:any){const definition=normalizeSkillDefinition(input),id=crypto.randomUUID(),now=new Date().toISOString(),payload=JSON.stringify({...definition,id});db().prepare('INSERT INTO skills(id,name,status,config_json,version,updated_at) VALUES(?,?,?,?,1,?)').run(id,definition.name,definition.status,payload,now);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'skill.create','skill',id,JSON.stringify({procedureId:definition.procedureId,sourceCount:definition.allowedSources.length,agentReferenceCount:definition.assignedAgentWorkflowIds.length,approvalClass:definition.approvalClass}),now);return{id,...definition,executable:definition.status==='active',version:1,updatedAt:now}}
export function updateSkillDefinition(id:string,input:any){const current=listRecords('skills').find(record=>record.id===id);if(!current)throw new Error('Skill nicht gefunden');const definition=normalizeSkillDefinition(input,current),now=new Date().toISOString(),payload=JSON.stringify({...definition,id}),result=db().prepare('UPDATE skills SET name=?,status=?,config_json=?,version=version+1,updated_at=? WHERE id=?').run(definition.name,definition.status,payload,now,id);if(!result.changes)throw new Error('Skill nicht aktualisiert');db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'skill.update','skill',id,JSON.stringify({procedureId:definition.procedureId,sourceCount:definition.allowedSources.length,agentReferenceCount:definition.assignedAgentWorkflowIds.length,approvalClass:definition.approvalClass}),now);return{id,...definition,executable:definition.status==='active',version:Number(current.version)+1,updatedAt:now}}
export function archiveSkillDefinition(id:string){const now=new Date().toISOString(),result=db().prepare("UPDATE skills SET status='archived',version=version+1,updated_at=? WHERE id=? AND status<>'archived'").run(now,id);if(!result.changes)throw new Error('Skill nicht gefunden');db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'skill.archive','skill',id,JSON.stringify({reversible:true,externalActionsPerformed:false}),now);return{archived:true,id,deleted:false}}
export function saveSkillRun(skill:any,preview:any){if(!skill?.id||skill.status!=='active'||skill.executionMode!=='deterministic-local'||skill.approvalClass!=='local_read_proposal')throw new Error('Skill ist nicht sicher ausführbar');if(preview?.writesPerformed!==false||preview?.externalActionsPerformed!==false||preview?.modelCalls!==false||preview?.networkCalls!==false||preview?.fileWrites!==false)throw new Error('Unsicherer Skill-Output abgewiesen');const id=crypto.randomUUID(),now=new Date().toISOString(),sourceEvidence=preview.sourceEvidence||{},safety={approvalClass:'local_read_proposal',arbitraryCode:false,shell:false,dynamicImports:false,network:false,fileWrites:false,modelCalls:false,externalWrites:false,backgroundChains:false};db().prepare('INSERT INTO skill_runs(id,skill_id,definition_version,status,input_enc,output_enc,source_json,safety_json,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,1,?,?)').run(id,skill.id,Number(skill.version||1),'preview',encryptSensitive(preview.input||{}),encryptSensitive({summary:preview.summary,items:preview.items,deterministicSteps:preview.deterministicSteps}),JSON.stringify(sourceEvidence),JSON.stringify(safety),now,now);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'skill.run.preview','skill_run',id,JSON.stringify({skillId:skill.id,definitionVersion:Number(skill.version||1),procedureId:skill.procedureId,itemCount:Array.isArray(preview.items)?preview.items.length:0,sourceCount:Object.keys(sourceEvidence).length,writesPerformed:false,modelCalls:false,networkCalls:false}),now);return{id,skillId:skill.id,definitionVersion:Number(skill.version||1),status:'preview',input:preview.input||{},output:{summary:preview.summary,items:preview.items,deterministicSteps:preview.deterministicSteps},sourceEvidence,safety,version:1,createdAt:now,updatedAt:now}}
export function listSkillRuns(limit=30){const safeLimit=Math.min(50,Math.max(1,Math.trunc(limit)||30));const rows=db().prepare("SELECT * FROM skill_runs WHERE status<>'archived' ORDER BY updated_at DESC LIMIT ?").all(safeLimit) as Array<Record<string,any>>;return rows.map(row=>({id:row.id,skillId:row.skill_id,definitionVersion:row.definition_version,status:row.status,input:decryptSensitive(String(row.input_enc)),output:decryptSensitive(String(row.output_enc)),sourceEvidence:JSON.parse(String(row.source_json||'{}')),safety:JSON.parse(String(row.safety_json||'{}')),version:row.version,createdAt:row.created_at,updatedAt:row.updated_at}))}
export function reviewSkillRun(id:string){const current=listSkillRuns(50).find(run=>run.id===id);if(!current)throw new Error('Skill-Lauf nicht gefunden');if(current.status!=='preview')throw new Error('Nur offene Vorschauen können geprüft werden');const now=new Date().toISOString(),result=db().prepare("UPDATE skill_runs SET status='reviewed',version=version+1,updated_at=? WHERE id=? AND status='preview'").run(now,id);if(!result.changes)throw new Error('Skill-Lauf wurde bereits geändert');db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'skill.run.review','skill_run',id,JSON.stringify({skillId:current.skillId,definitionVersion:current.definitionVersion,writesPerformed:false,externalActionsPerformed:false}),now);return{...current,status:'reviewed',version:Number(current.version)+1,updatedAt:now}}
export function saveVaultWriteProposal(proposal:any,approvalToken:string){if(proposal?.approvalClass!=='vault_exact_diff'||proposal?.applyAvailable!==false||proposal?.writesPerformed!==false||proposal?.existingNotesModified!==0)throw new Error('Nur schreibfreie exakte Vault-Vorschläge sind erlaubt');if(!approvalToken||approvalToken.length<32)throw new Error('Approval-Token fehlt');const id=crypto.randomUUID(),now=new Date().toISOString(),expiresAt=new Date(Date.now()+15*60*1000).toISOString(),status=proposal.conflict?'conflict':'review_required';db().prepare('INSERT INTO vault_write_proposals(id,proposal_type,status,target_path_enc,proposal_enc,approval_hash,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)').run(id,proposal.proposalType,status,encryptSensitive({targetPath:proposal.targetPath}),encryptSensitive(proposal),crypto.createHash('sha256').update(approvalToken).digest('hex'),expiresAt,now,now);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'vault_write.preview','vault_write_proposal',id,JSON.stringify({proposalType:proposal.proposalType,status,conflict:Boolean(proposal.conflict),approvalClass:'vault_exact_diff',writesPerformed:false,existingNotesModified:0}),now);return{id,...proposal,status,expiresAt,version:1,createdAt:now,updatedAt:now}}
export function listVaultWriteProposals(limit=12){const safeLimit=Math.min(20,Math.max(1,Math.trunc(limit)||12));const rows=db().prepare("SELECT * FROM vault_write_proposals WHERE status<>'archived' ORDER BY updated_at DESC LIMIT ?").all(safeLimit) as Array<Record<string,any>>;return rows.map(row=>{const target=decryptSensitive(String(row.target_path_enc)),proposal=decryptSensitive(String(row.proposal_enc));return{id:row.id,...proposal,targetPath:target.targetPath,status:row.status,expiresAt:row.expires_at,version:row.version,createdAt:row.created_at,updatedAt:row.updated_at,applyAvailable:false,writesPerformed:false}})}
export function approveVaultWriteProposal(id:string,approvalToken:string,phrase:string,revalidation:any){const row=db().prepare('SELECT * FROM vault_write_proposals WHERE id=?').get(id) as Record<string,any>|undefined;if(!row)throw new Error('Vault-Vorschlag nicht gefunden');if(row.status!=='review_required')throw new Error('Vorschlag ist nicht freigabebereit');if(Date.now()>Date.parse(String(row.expires_at)))throw new Error('Freigabevorschlag ist abgelaufen');if(phrase!=='OBSIDIAN DIFF FREIGEBEN')throw new Error('Exakte Freigabephrase stimmt nicht');const supplied=crypto.createHash('sha256').update(String(approvalToken||'')).digest(),expected=Buffer.from(String(row.approval_hash),'hex');if(expected.length!==supplied.length||!crypto.timingSafeEqual(expected,supplied))throw new Error('Freigabe-Token ist ungültig');if(revalidation?.conflict||!revalidation?.currentHashMatches||!revalidation?.targetPathMatches)throw new Error('Vault-Ziel hat sich geändert; neue Vorschau erforderlich');const now=new Date().toISOString();db().prepare("UPDATE vault_write_proposals SET status='approved_pending_apply',version=version+1,updated_at=? WHERE id=? AND status='review_required'").run(now,id);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'vault_write.approve_preview','vault_write_proposal',id,JSON.stringify({proposalType:row.proposal_type,status:'approved_pending_apply',applyAvailable:false,writesPerformed:false,existingNotesModified:0}),now);return{...listVaultWriteProposals(20).find(item=>item.id===id),status:'approved_pending_apply',applyAvailable:false,writesPerformed:false}}
export function validateWeeklyPlan(input:any){
  if(input?.timezone!=='Europe/Berlin')throw new Error('Wochenplan-Zeitzone muss Europe/Berlin sein');
  if(!Array.isArray(input?.outcomes)||input.outcomes.length>3)throw new Error('Wochenplan darf höchstens 3 Outcomes enthalten');
  if(!Array.isArray(input?.blocks)||input.blocks.length>3)throw new Error('Wochenplan darf höchstens 3 Fokusvorschläge enthalten');
  const outcomeIds=input.outcomes.map((item:any)=>String(item.id||''));
  if(outcomeIds.some((id:string)=>!id)||new Set(outcomeIds).size!==outcomeIds.length)throw new Error('Outcome-IDs müssen eindeutig sein');
  const buffer=Number(input?.capacity?.bufferPercent);
  if(!Number.isFinite(buffer)||buffer<30||buffer>40)throw new Error('Puffer muss 30–40 Prozent betragen');
  if(input?.backgroundWrites!==false||input?.writesPerformed!==false)throw new Error('Hintergrundwrites sind verboten');
  const windowStart=Date.parse(input?.constraints?.windowStart),windowEnd=Date.parse(input?.constraints?.windowEnd);
  if(!Number.isFinite(windowStart)||!Number.isFinite(windowEnd)||windowEnd<=windowStart)throw new Error('8-Tage-Fenster ungültig');
  const blockIds=new Set<string>(),trainingDays=new Set((input?.constraints?.trainingDays||[]).map(String)),selectedCalendars=new Set((input?.constraints?.selectedCalendarIds||[]).map(String));
  const busyIntervals=(input?.constraints?.busyIntervals||[]).map((item:any)=>({start:Date.parse(item.start),end:Date.parse(item.end)})).filter((item:any)=>Number.isFinite(item.start)&&Number.isFinite(item.end)&&item.end>item.start);
  const accepted:Array<{start:number;end:number}>=[];
  const berlinDay=(instant:number)=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(instant));
  for(const block of input.blocks){
    if(!block.id||blockIds.has(block.id))throw new Error('Fokusblock-IDs müssen eindeutig sein');blockIds.add(block.id);
    if(!outcomeIds.includes(String(block.outcomeId)))throw new Error('Fokusblock verweist auf ein fremdes Outcome');
    if(block.status!=='proposal'||block.writesPerformed!==false)throw new Error('Fokusblock muss ein ungeschriebener Vorschlag sein');
    if(block.timezone!=='Europe/Berlin')throw new Error('Fokusblock-Zeitzone ungültig');
    if(!selectedCalendars.has(String(block.calendarId)))throw new Error('Fokusblock verwendet einen nicht ausgewählten Kalender');
    const start=Date.parse(block.start),end=Date.parse(block.end);
    if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)throw new Error('Fokusblock-Zeitfenster ungültig');
    if(start<windowStart||end>windowEnd)throw new Error('Fokusblock liegt außerhalb des 8-Tage-Fensters');
    if(trainingDays.has(berlinDay(start)))throw new Error('Fokusblock liegt auf einem Trainingstag');
    if(busyIntervals.some((item:any)=>start<item.end&&end>item.start))throw new Error('Fokusblock überschneidet einen Kalendertermin');
    if(accepted.some(item=>start<item.end&&end>item.start))throw new Error('Fokusblöcke überschneiden sich');
    accepted.push({start,end});
  }
  return input;
}
export function saveWeeklyPlan(input:any){const exact=validateWeeklyPlan(input),id=crypto.randomUUID(),now=new Date().toISOString(),status='proposal',plan={...exact,id,status,decisions:{selectedOutcomeIds:[],selectedBlockIds:[],reviewed:false},createdAt:now,updatedAt:now},database=db();database.exec('BEGIN IMMEDIATE');try{database.prepare('INSERT INTO weekly_plans(id,week_start,status,plan_enc,updated_at) VALUES(?,?,?,?,?)').run(id,String(plan.weekStart),status,encryptSensitive(plan),now);for(const[outcomeRank,outcome]of plan.outcomes.entries())database.prepare('INSERT INTO weekly_outcomes(id,plan_id,source_kind,source_id,rank,status,title_enc,updated_at) VALUES(?,?,?,?,?,?,?,?)').run(outcome.id,id,outcome.sourceKind,outcome.sourceId||null,outcomeRank+1,'proposal',encryptSensitive({title:outcome.title,area:outcome.area||'',reason:outcome.reason||''}),now);for(const block of plan.blocks)database.prepare('INSERT INTO focus_proposals(id,plan_id,outcome_id,target_calendar_id,start_at,end_at,timezone,status,proposal_enc,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)').run(block.id,id,block.outcomeId,block.calendarId,block.start,block.end,block.timezone,'proposal',encryptSensitive({title:block.title,calendarName:block.calendarName||''}),now);database.prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'weekly_plan.generate','weekly_plan',id,JSON.stringify({outcomeCount:plan.outcomes.length,blockCount:plan.blocks.length,bufferPercent:plan.capacity.bufferPercent,writesPerformed:false}),now);database.exec('COMMIT')}catch(error){database.exec('ROLLBACK');throw error}return plan}
export function latestWeeklyPlan(){const row=db().prepare('SELECT id,status,plan_enc,version,updated_at FROM weekly_plans ORDER BY updated_at DESC LIMIT 1').get() as {id:string;status:string;plan_enc:string;version:number;updated_at:string}|undefined;if(!row)return null;return{...decryptSensitive(row.plan_enc),id:row.id,status:row.status,version:row.version,updatedAt:row.updated_at}}
export function listWeeklyPlanSummaries(limit=8){const safeLimit=Math.min(12,Math.max(1,Math.trunc(limit)||8));const rows=db().prepare('SELECT id,status,plan_enc,version,updated_at FROM weekly_plans ORDER BY updated_at DESC LIMIT ?').all(safeLimit) as Array<{id:string;status:string;plan_enc:string;version:number;updated_at:string}>;return rows.map(row=>{const plan=decryptSensitive(row.plan_enc);return{id:row.id,status:row.status,weekStart:plan.weekStart,windowEnd:plan.windowEnd,timezone:plan.timezone,outcomeCount:Array.isArray(plan.outcomes)?plan.outcomes.length:0,blockCount:Array.isArray(plan.blocks)?plan.blocks.length:0,selectedOutcomeCount:Array.isArray(plan.decisions?.selectedOutcomeIds)?plan.decisions.selectedOutcomeIds.length:0,selectedBlockCount:Array.isArray(plan.decisions?.selectedBlockIds)?plan.decisions.selectedBlockIds.length:0,bufferPercent:Number(plan.capacity?.bufferPercent||0),version:row.version,updatedAt:row.updated_at,writesPerformed:false}})}
export function projectWorkspace(projectId:string){const project=listRecords('projects').find(item=>item.id===projectId);if(!project)throw new Error('Projekt nicht gefunden');const tasks=listRecords('tasks').filter(item=>item.projectId===projectId),inbox=listRecords('inbox_items').filter(item=>item.projectId===projectId),resources=inbox.filter(item=>['link','dateiverweis'].includes(String(item.itemType))),relatedIds=[projectId,...tasks.map(item=>item.id),...inbox.map(item=>item.id)],placeholders=relatedIds.map(()=>'?').join(',');const audit=(db().prepare(`SELECT action,entity_type,created_at FROM audit_log WHERE entity_id IN (${placeholders}) ORDER BY created_at DESC LIMIT 20`).all(...relatedIds) as Array<{action:string;entity_type:string|null;created_at:string}>).map(row=>({action:row.action,entityType:row.entity_type||'system',createdAt:row.created_at}));const weekly=(db().prepare('SELECT id,status,plan_enc,updated_at FROM weekly_plans ORDER BY updated_at DESC LIMIT 12').all() as Array<{id:string;status:string;plan_enc:string;updated_at:string}>).flatMap(row=>{const plan=decryptSensitive(row.plan_enc),outcome=(plan.outcomes||[]).find((item:any)=>item.sourceKind==='project'&&item.sourceId===projectId);if(!outcome)return[];return[{planId:row.id,weekStart:plan.weekStart,windowEnd:plan.windowEnd,status:row.status,selected:Boolean(plan.decisions?.selectedOutcomeIds?.includes(outcome.id)),blockProposed:Boolean((plan.blocks||[]).some((block:any)=>block.outcomeId===outcome.id)),updatedAt:row.updated_at}]});return{projectId,counts:{tasks:tasks.length,openTasks:tasks.filter(item=>!item.done).length,inbox:inbox.length,resources:resources.length,weeklyLinks:weekly.length},weekly,audit,source:'laptop-shared-store',personalContentExposed:false,writesPerformed:false}}
const workflowIds=['project_coach','faith_reflection','health_planner','finance_overview','relationship_care'] as const;
function assertWorkflowId(value:unknown){if(!(workflowIds as readonly unknown[]).includes(value))throw new Error('Unbekannter Agenten-Workflow');return String(value)}
export function saveAgentWorkflowRun(proposal:any){const workflowId=assertWorkflowId(proposal?.workflowId);if(proposal?.provider!=='local-rules'||proposal?.model!=='none'||proposal?.externalActionsPerformed!==false||proposal?.backgroundActions!==false)throw new Error('Nur lokale Vorschlagsläufe ohne Aktionen sind erlaubt');if(!Array.isArray(proposal?.suggestions)||proposal.suggestions.length>5)throw new Error('Workflow darf höchstens 5 Vorschläge enthalten');const id=crypto.randomUUID(),now=new Date().toISOString(),source=proposal.sourceEvidence||{},output={summary:String(proposal.summary||''),suggestions:proposal.suggestions,provider:'local-rules',model:'none',cost:'free-local',professionalAdvice:false,externalActionsPerformed:false,backgroundActions:false};db().prepare('INSERT INTO agent_workflow_runs(id,workflow_id,status,current_step,input_enc,output_enc,source_json,decision_json,resume_enc,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(id,workflowId,'proposal','review',encryptSensitive({input:String(proposal.input||'')}),encryptSensitive(output),JSON.stringify(source),JSON.stringify({selectedSuggestionIds:[],reviewed:false,externalActionApproved:false}),encryptSensitive({currentStep:'review'}),now,now);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'agent_workflow.generate','agent_workflow',id,JSON.stringify({workflowId,suggestionCount:proposal.suggestions.length,provider:'local-rules',paidModel:false,externalActionsPerformed:false}),now);return{id,workflowId,status:'proposal',currentStep:'review',input:String(proposal.input||''),output,sourceEvidence:source,decision:{selectedSuggestionIds:[],reviewed:false,externalActionApproved:false},version:1,createdAt:now,updatedAt:now}}
export function listAgentWorkflowRuns(limit=20){const safeLimit=Math.min(50,Math.max(1,Math.trunc(limit)||20));const rows=db().prepare("SELECT * FROM agent_workflow_runs WHERE status<>'archived' ORDER BY updated_at DESC LIMIT ?").all(safeLimit) as Array<Record<string,any>>;return rows.map(row=>{const input=decryptSensitive(String(row.input_enc)),output=decryptSensitive(String(row.output_enc)),resume=decryptSensitive(String(row.resume_enc));return{id:row.id,workflowId:row.workflow_id,status:row.status,currentStep:row.current_step,input:input.input,output,sourceEvidence:JSON.parse(String(row.source_json||'{}')),decision:JSON.parse(String(row.decision_json||'{}')),resume,version:row.version,createdAt:row.created_at,updatedAt:row.updated_at}})}
export function transitionAgentWorkflowRun(id:string,action:unknown,input:any={}){const current=listAgentWorkflowRuns(50).find(run=>run.id===id);if(!current)throw new Error('Workflow-Lauf nicht gefunden');if(!['review','pause','resume','archive'].includes(String(action)))throw new Error('Ungültiger Workflow-Schritt');let status=current.status,currentStep=current.currentStep,decision=current.decision;if(action==='review'){const raw=(Array.isArray(input.selectedSuggestionIds)?input.selectedSuggestionIds:[]).map(String),allowed=new Set((current.output.suggestions||[]).map((item:any)=>item.id));if(new Set(raw).size!==raw.length||raw.some((value:string)=>!allowed.has(value)))throw new Error('Review enthält fremde oder doppelte Vorschläge');status='reviewed';currentStep='complete';decision={selectedSuggestionIds:raw,reviewed:true,reviewedAt:new Date().toISOString(),externalActionApproved:false}}else if(action==='pause'){if(current.status==='reviewed')throw new Error('Abgeschlossener Review kann nicht pausiert werden');status='paused';currentStep='paused'}else if(action==='resume'){if(current.status!=='paused')throw new Error('Nur pausierte Läufe können fortgesetzt werden');status='proposal';currentStep='review'}else{status='archived';currentStep='archived'}const now=new Date().toISOString();db().prepare('UPDATE agent_workflow_runs SET status=?,current_step=?,decision_json=?,resume_enc=?,version=version+1,updated_at=? WHERE id=?').run(status,currentStep,JSON.stringify(decision),encryptSensitive({currentStep,previousStatus:current.status,resumed:action==='resume'}),now,id);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),`agent_workflow.${action}`,'agent_workflow',id,JSON.stringify({workflowId:current.workflowId,status,selectedSuggestionCount:decision.selectedSuggestionIds?.length||0,externalActionsPerformed:false}),now);return{...current,status,currentStep,decision,resume:{currentStep,previousStatus:current.status,resumed:action==='resume'},version:Number(current.version)+1,updatedAt:now}}
export function validateWeeklyReview(current:any,input:any){const outcomeIds=new Set(current.outcomes.map((item:any)=>item.id)),blockIds=new Set(current.blocks.map((item:any)=>item.id)),selectedOutcomeIds=(Array.isArray(input.selectedOutcomeIds)?input.selectedOutcomeIds:[]).map(String),selectedBlockIds=(Array.isArray(input.selectedBlockIds)?input.selectedBlockIds:[]).map(String);if(new Set(selectedOutcomeIds).size!==selectedOutcomeIds.length||new Set(selectedBlockIds).size!==selectedBlockIds.length)throw new Error('Doppelte Auswahl-IDs sind nicht erlaubt');if(selectedOutcomeIds.some((value:string)=>!outcomeIds.has(value))||selectedBlockIds.some((value:string)=>!blockIds.has(value)))throw new Error('Auswahl enthält fremde IDs');if(selectedOutcomeIds.length>3||selectedBlockIds.length>3)throw new Error('Maximal drei Ziele und Blöcke auswählen');if(selectedBlockIds.some((value:string)=>!selectedOutcomeIds.includes(current.blocks.find((block:any)=>block.id===value)?.outcomeId)))throw new Error('Ein Block erfordert sein zugehöriges Outcome');if(!selectedOutcomeIds.length)throw new Error('Mindestens ein Wochenziel auswählen');return{selectedOutcomeIds,selectedBlockIds}}
export function reviewWeeklyPlan(id:string,input:any){const row=db().prepare('SELECT id,status,plan_enc,version,updated_at FROM weekly_plans WHERE id=?').get(id) as {id:string;status:string;plan_enc:string;version:number;updated_at:string}|undefined;if(!row)throw new Error('Wochenplan nicht gefunden');const current={...decryptSensitive(row.plan_enc),id:row.id,status:row.status,version:row.version,updatedAt:row.updated_at},{selectedOutcomeIds,selectedBlockIds}=validateWeeklyReview(current,input);const now=new Date().toISOString(),status='reviewed',plan={...current,status,decisions:{selectedOutcomeIds,selectedBlockIds,reviewed:true,reviewedAt:now},updatedAt:now};db().prepare('UPDATE weekly_plans SET status=?,plan_enc=?,version=version+1,updated_at=? WHERE id=?').run(status,encryptSensitive(plan),now,id);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'weekly_plan.review','weekly_plan',id,JSON.stringify({selectedOutcomeCount:selectedOutcomeIds.length,selectedBlockCount:selectedBlockIds.length,writesPerformed:false}),now);return{...plan,version:Number(current.version||1)+1}}
export function listAuditEntries(limit=8){const safeLimit=Math.min(20,Math.max(1,Math.trunc(limit)||8));const rows=db().prepare('SELECT action,entity_type,created_at FROM audit_log ORDER BY created_at DESC LIMIT ?').all(safeLimit) as Array<{action:string;entity_type:string|null;created_at:string}>;return rows.map(row=>({action:row.action,entityType:row.entity_type||'system',createdAt:row.created_at}))}
const preferenceIds=['theme','branding'] as const;export type PreferenceId=typeof preferenceIds[number];
export function isPreferenceId(value:string):value is PreferenceId{return(preferenceIds as readonly string[]).includes(value)}
const defaultBranding={name:'Agentic OS',short:'AOS',accent:'#27d3ff'};
function validatePreference(id:PreferenceId,value:unknown){
  if(id==='theme'){
    if(!['dark','light'].includes(String(value)))throw new Error('Ungültiges Theme');
    return String(value);
  }
  const input=value&&typeof value==='object'?value as Record<string,unknown>:{};
  const name=String(input.name||'').trim(),short=String(input.short||'').trim().toUpperCase(),accent=String(input.accent||'').toLowerCase();
  if(name.length<2||name.length>60)throw new Error('Produktname muss 2 bis 60 Zeichen haben');
  if(!/^[A-ZÄÖÜ0-9]{1,3}$/.test(short))throw new Error('Kurzname muss 1 bis 3 Buchstaben oder Ziffern haben');
  if(!/^#[0-9a-f]{6}$/.test(accent))throw new Error('Ungültige Akzentfarbe');
  return{name,short,accent};
}
export function getPreference(id:PreferenceId){const row=db().prepare('SELECT evidence_json,updated_at FROM progress_items WHERE id=?').get(`preference:${id}`) as {evidence_json:string;updated_at:string}|undefined;if(!row)return{id,value:id==='theme'?'dark':defaultBranding,source:'default',updatedAt:null};const data=JSON.parse(row.evidence_json);return{id,value:data.value,source:'shared-store',updatedAt:row.updated_at}}
export function setPreference(id:PreferenceId,value:unknown){const validated=validatePreference(id,value),now=new Date().toISOString(),key=`preference:${id}`,payload=JSON.stringify({value:validated});db().prepare(`INSERT INTO progress_items(id,phase,status,evidence_json,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET evidence_json=excluded.evidence_json,version=progress_items.version+1,updated_at=excluded.updated_at`).run(key,'preferences','active',payload,now);db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'preference.update','preference',id,JSON.stringify({source:'agentic-os-ui'}),now);return{id,value:validated,source:'shared-store',updatedAt:now}}
const backupDir=()=>path.join(stateDir(),'backups');
const backupNamePattern=/^agentic-os-[\w-]+\.sqlite$/;
function backupPath(fileName:string){if(path.basename(fileName)!==fileName||!backupNamePattern.test(fileName))throw new Error('Ungültige Backupdatei');const resolved=path.resolve(backupDir(),fileName),root=path.resolve(backupDir())+path.sep;if(!resolved.startsWith(root))throw new Error('Backupdatei liegt außerhalb des privaten Backupordners');return resolved}
function sha256File(file:string){return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex')}
function backupMetadata(file:string){const stat=fs.statSync(file);return{fileName:path.basename(file),createdAt:stat.birthtime.toISOString(),bytes:stat.size,sha256:sha256File(file),localOnly:true}}
export function listStoreBackups(){const dir=backupDir();if(!fs.existsSync(dir))return[];return fs.readdirSync(dir,{withFileTypes:true}).filter(entry=>entry.isFile()&&backupNamePattern.test(entry.name)).map(entry=>backupMetadata(path.join(dir,entry.name))).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}
export function backupStore(){db().exec('PRAGMA wal_checkpoint(FULL)');const dir=backupDir();fs.mkdirSync(dir,{recursive:true});const file=path.join(dir,`agentic-os-${new Date().toISOString().replace(/[:.]/g,'-')}.sqlite`);db().exec(`VACUUM INTO '${file.replaceAll("'","''")}'`);try{fs.chmodSync(file,0o600)}catch{}const metadata=backupMetadata(file),now=new Date().toISOString();db().prepare('INSERT INTO audit_log(id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?)').run(crypto.randomUUID(),'backup.create','system',null,JSON.stringify({fileName:metadata.fileName,bytes:metadata.bytes,localOnly:true,externalTransfer:false}),now);return{created:true,...metadata,keyIncluded:false,externalTransfer:false}}
export function previewRestore(fileName:string){const file=backupPath(fileName);if(!fs.existsSync(file))throw new Error('Backupdatei nicht gefunden');const candidate=new DatabaseSync(file,{readOnly:true});try{const integrity=String(Object.values(candidate.prepare('PRAGMA integrity_check').get()||{})[0]||'unknown'),version=Number((candidate.prepare('SELECT MAX(version) AS version FROM schema_migrations').get() as {version:number|null}).version||0);if(integrity!=='ok')throw new Error('Integritätsprüfung des Backups fehlgeschlagen');const backupCounts=Object.fromEntries(operationalKinds.map(table=>{try{return[table,Number((candidate.prepare(`SELECT COUNT(*) AS count FROM ${table}`).get() as {count:number}).count)]}catch{return[table,0]}})),current=storeStatus().counts,changedTables=operationalKinds.filter(table=>Number(backupCounts[table])!==Number(current[table]));return{...backupMetadata(file),schemaVersion:version,integrity,status:'review_required',restorePerformed:false,applyAvailable:false,currentCounts:current,backupCounts,changedTables,conflictReviewRequired:changedTables.length>0,keyIncluded:false,restorePlan:['Aktuelle Datenbank separat sichern','Backup-Hash und Integrität erneut prüfen','Dienst atomar anhalten','Nur nach exakter Freigabe ersetzen','Start und Datensatz-Zähler prüfen','Bei Abweichung auf Vorher-Backup zurückrollen']}}finally{candidate.close()}}
export function signLocalSession(value:string){const secret=process.env.AUTH_SECRET;if(!secret)throw new Error('AUTH_SECRET fehlt');return`${value}.${crypto.createHmac('sha256',secret).update(value).digest('base64url')}`}
export function verifyLocalSession(value?:string){if(!value)return false;const split=value.lastIndexOf('.');if(split<1)return false;const raw=value.slice(0,split),expected=signLocalSession(raw);return value.length===expected.length&&crypto.timingSafeEqual(Buffer.from(value),Buffer.from(expected))}
export function trustedPrivateHost(host:string){const name=host.split(':')[0].toLowerCase();return name==='localhost'||name==='127.0.0.1'||name.endsWith('.ts.net')||/^10\.|^192\.168\.|^172\.(1[6-9]|2\d|3[01])\./.test(name)}
